'use strict';

var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var compareOrders = require( './../lib' );

var isCompareOrder = contains( compareOrders() );

var bool = isCompareOrder( 'ascending' );
console.log( bool );
// => true

bool = isCompareOrder( 'descending' );
console.log( bool );
// => true

bool = isCompareOrder( 'beep' );
console.log( bool );
// => false

bool = isCompareOrder( 'boop' );
console.log( bool );
// => false
